def is_semiperfect_number(n):
    if n <= 0:
        return False
    divs = [i for i in range(1, n) if n % i == 0]
    dp = {0}
    for d in divs:
        new = set()
        for s in dp:
            if s + d <= n:
                new.add(s + d)
        dp |= new
    return n in dp

def has_no_sequential_run(s):
    run = 1
    for i in range(1, len(s)):
        if ord(s[i]) == ord(s[i - 1]) + 1:
            run += 1
            if run >= 3:
                return False
        else:
            run = 1
    return True

def mask_string(s, visible):
    if len(s) <= 2 * visible:
        return s
    return s[:visible] + '*' * (len(s) - 2 * visible) + s[len(s)-visible:]

def top_k_names_ties_by_length_then_alpha(records, k):
    ordered = sorted(records, key=lambda r: (-r[1], len(r[0]), r[0]))
    return [r[0] for r in ordered[:k]]

def max_product_of_two(lst):
    s = sorted(lst)
    return max(s[-1] * s[-2], s[0] * s[1])

def is_valid_isbn13(s):
    s = s.replace('-', '')
    if len(s) != 13 or not s.isdigit():
        return False
    total = 0
    for i, ch in enumerate(s):
        weight = 1 if i % 2 == 0 else 3
        total += int(ch) * weight
    return total % 10 == 0

def sort_by_vowel_count(words):
    vowels = set('aeiouAEIOU')
    def vcount(w):
        return sum(1 for c in w if c in vowels)
    return sorted(words, key=lambda w: (vcount(w), w))

def char_index_map(s):
    result = {}
    for i, c in enumerate(s):
        result.setdefault(c, []).append(i)
    return result

def rank_unique_by_first_occurrence_frequency(items):
    from collections import Counter
    c = Counter(items)
    first_idx = {}
    for i, x in enumerate(items):
        if x not in first_idx:
            first_idx[x] = i
    uniq = list(first_idx.keys())
    return sorted(uniq, key=lambda x: (-c[x], first_idx[x]))

def percentile_rank_strict(scores, value):
    if not scores:
        return 0.0
    count = sum(1 for s in scores if s < value)
    return round(100 * count / len(scores), 2)

def closest_k_indices_to_target(nums, target, k):
    idx = sorted(range(len(nums)), key=lambda i: (abs(nums[i] - target), i))
    return idx[:k]

def is_prime_power(n):
    if n < 2:
        return False
    temp = n
    d = 2
    prime_found = None
    while d * d <= temp:
        if temp % d == 0:
            prime_found = d
            while temp % d == 0:
                temp //= d
            break
        d += 1
    if prime_found is None:
        return True
    return temp == 1

def pad_to_length(lst, n, pad):
    if len(lst) >= n:
        return lst[:n]
    return lst + [pad] * (n - len(lst))

def count_leading_zeros(s):
    count = 0
    for ch in s:
        if ch == '0':
            count += 1
        else:
            break
    return count

def alternating_sum_abs_diffs(lst):
    if len(lst) < 2:
        return 0
    diffs = [abs(lst[i + 1] - lst[i]) for i in range(len(lst) - 1)]
    total = 0
    for i, d in enumerate(diffs):
        total += d if i % 2 == 0 else -d
    return total

def count_bigrams(text):
    words = text.split()
    d = {}
    for i in range(len(words) - 1):
        key = words[i] + " " + words[i + 1]
        d[key] = d.get(key, 0) + 1
    return d

def differences_from_first(lst):
    if not lst:
        return []
    first = lst[0]
    return [x - first for x in lst]

def sort_by_factor_count(nums):
    def divcount(n):
        return sum(1 for d in range(1, n + 1) if n % d == 0)
    return sorted(nums, key=lambda n: (divcount(n), n))

def rotate_left(lst, k):
    if not lst:
        return []
    k = k % len(lst)
    return lst[k:] + lst[:k]

def longest_common_prefix_case_insensitive(strs):
    if not strs:
        return ""
    first = strs[0]
    length = len(first)
    for s in strs[1:]:
        i = 0
        while i < length and i < len(s) and first[i].lower() == s[i].lower():
            i += 1
        length = i
        if length == 0:
            break
    return first[:length]

def is_valid_paren_bracket_sequence(s):
    pairs = {')': '(', ']': '['}
    opens = set(pairs.values())
    stack = []
    for c in s:
        if c in opens:
            stack.append(c)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
        else:
            return False
    return not stack

def move_char_to_front(s, ch):
    idx = s.find(ch)
    if idx == -1:
        return s
    return s[idx] + s[:idx] + s[idx + 1:]

def median_of_row_sums(matrix):
    sums = sorted(sum(row) for row in matrix)
    n = len(sums)
    mid = n // 2
    if n % 2 == 1:
        return float(sums[mid])
    return (sums[mid - 1] + sums[mid]) / 2

def is_valid_semver(s):
    parts = s.split('.')
    if len(parts) != 3:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
    return True
